/**
 * Astrology App — glyph and ornament data for react-native-svg.
 * Generated from the design system. Data only.
 *
 * GLYPHS: stroke-only line drawings. Render each element with react-native-svg (Path / Circle / Rect),
 *   fill="none", stroke={color}, strokeLinecap="round", strokeLinejoin="round", strokeWidth = viewBox's default.
 *   Elements with `fill: true` are solid: fill={color}, stroke="none".
 * ORNAMENTS: complete SVG XML for <SvgXml xml=... color={ink} />. Ink is `currentColor`;
 *   replace "__SURFACE__" with the theme's `surface` before rendering (cut-out shapes).
 * SKY: Screen background. Replace "__HAIRLINE__" and "__STAR__" with theme `hairline` / `star`.
 */

export type GlyphElement =
  | { el: "path"; d: string; fill?: true }
  | { el: "circle"; cx: number | string; cy: number | string; r: number | string; fill?: true }
  | { el: "rect"; x: number | string; y: number | string; width: number | string; height: number | string; rx?: number | string; fill?: true };

