/** TraitCard decoration in a 100×160 box: dots [cx, cy, r] and four-point sparkles [cx, cy, size]. */
export const traitScatter = {
  dots: [[16, 36, 1.1], [84, 32, 1.1], [11, 52, 0.9], [90, 50, 1.3], [8, 70, 1.1], [92, 74, 0.9], [8, 90, 0.9], [92, 92, 1.2], [11, 110, 1.1], [88, 112, 0.9], [20, 126, 0.8], [76, 128, 1.2], [30, 40, 0.8], [70, 42, 0.8], [36, 120, 0.7], [64, 118, 0.7]],
  sparkles: [[22, 22, 3.2], [78, 140, 3.2], [91, 62, 2.4], [9, 100, 2.4]],
} as const;

/** Four-point sparkle path centred on (x, y) with half-size s (used by traitScatter.sparkles). */
export const sparklePath = (x: number, y: number, s: number): string => {
  const k = s * 0.22;
  return `M${x} ${y - s}Q${x + k} ${y - k} ${x + s} ${y}Q${x + k} ${y + k} ${x} ${y + s}Q${x - k} ${y + k} ${x - s} ${y}Q${x - k} ${y - k} ${x} ${y - s}Z`;
};
